599	    pub fn drain_upload_completions(&mut self) {
600	        while let Ok(result) = self.upload_rx.try_recv() {
601	            if let Some(inode) = self.inodes.get_mut(result.ino) {
602	                if inode.write_generation == result.write_generation {
603	                    if let inode::InodeKind::File { ref mut cid, .. } = inode.kind { *cid = result.new_cid.clone(); }
604	                }
605	            }
