607	                if inode.write_generation == result.write_generation {
608	                    if let Some(plaintext) = self.pending_content.remove(&result.ino) { self.content_cache.set(&result.new_cid, plaintext); }
609	                }
610	            }
611	            for pruned_cid in &result.pruned_cids {
612	                let api = self.api.clone(); let cid = pruned_cid.clone();
613	                self.rt.spawn(async move { let _ = cipherbox_api_client::ipfs::unpin_content(&api, &cid).await; });
614	            }
615	            if let Some(entry) = self.publish_queue.get_mut(&result.parent_ino) { entry.pending_uploads = entry.pending_uploads.saturating_sub(1); }
